// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    // fuzzed params: an address that will attempt to transfer ownership, and a candidate newOwner
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses non-zero to be meaningful
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // initial owner is address(0) because C.owner default is zero-address; ensure a non-zero owner
        // make some address become the owner: pick `caller` to become owner via direct storage manipulation is disallowed,
        // so we use the contract's transferOwnership under its current owner. The current owner is address(0),
        // but transferOwnership is onlyOwner guarded so only the owner (zero) can call — we cannot call as zero.
        // To set a nonzero owner for meaningful test, we simulate becoming owner by using vm.prank from address(0).
        // vm.prank supports arbitrarily setting msg.sender for tests, so we set owner = deploy-time zero-owner -> call

        // Set owner to `caller` by impersonating current owner (zero address)
        vm.prank(address(0));
        c.transferOwnership(caller);

        // Now the rule: only the current owner (caller) can successfully call transferOwnership.
        // Try to call transferOwnership as `caller` (should succeed on reference) and as a different address (should fail).

        // First, as the supposed owner (`caller`) call transferOwnership to set owner to newOwner.
        bool okOwnerCall;
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            okOwnerCall = true;
        } catch {
            okOwnerCall = false;
        }

        // Second, as a different address (use another fuzzed but derived address) attempt transferOwnership
        address other = address(uint160(uint256(keccak256(abi.encodePacked(caller, newOwner, block.timestamp)))));
        vm.assume(other != caller);

        bool okOtherCall;
        vm.prank(other);
        try c.transferOwnership(address(1)) {
            okOtherCall = true;
        } catch {
            okOtherCall = false;
        }

        // GENERAL RULE (single assertion): On the reference implementation, the true owner can call transferOwnership
        // successfully and a different address cannot. Therefore okOwnerCall == true and okOtherCall == false.
        // The buggy mutant inverts the onlyOwner check, so for some fuzzed inputs this will not hold.
        assertTrue(okOwnerCall && !okOtherCall);
    }
}
